!function(){"use strict";app.factory("etiquetaService",(function(mainService){let url="Inventario/Etiqueta/",service={getAll:function(query){return mainService.getData("get",url+"Get/"+query,null,!0).then(response=>{if("0"===response.code)throw response;if("1"===response.code){let etiquetas;return JSON.parse(response.payload).map(item=>({idEtiqueta:item.idEtiqueta,descripcion:item.descripcion,etiquetas:item.etiquetas,estado:item.estado}))}})},create:function(data){return mainService.getData("post",url+"Insert?json="+JSON.stringify(data),null,!0).then(response=>"0"===response.code?response:"1"===response.code?response:void 0)},update:function(id,data){return mainService.getData("put",url+"Update/"+id+"/?json="+JSON.stringify(data),null,!0).then(response=>"0"===response.code?response:"1"===response.code?response:void 0)},delete:function(id){return mainService.getData("delete",url+"Delete/"+id,null,!0).then(response=>"0"===response.code?response:"1"===response.code?response:void 0)}};return service}))}(window.angular);